/**
 * The brand mark as a base64 data URI.
 *
 * Bundled as a string rather than fetched at render time so the Open Graph
 * card never depends on a network round trip — a social scraper that times
 * out gets no second chance, and a link preview without the logo is worse
 * than a slightly larger function bundle.
 *
 * Generated from public/brand/logo-mark.svg. Regenerate if the mark changes.
 */
export const LOGO_MARK_DATA_URI =
  'data:image/svg+xml;base64,';
